<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'
import { request, query, session, downloadDividendReport, can, type Page } from '../api'
import { centsFromInput, money, dateTime } from '../domain.js'
import Modal from './Modal.vue'
import StatusBadge from './StatusBadge.vue'
const props=defineProps<{mode:'ledger'|'withdrawals'|'audit'}>()
const rows=ref<any[]>([]),total=ref(0),page=ref(1),loading=ref(false),busy=ref(false),error=ref(''),success=ref(''),selected=ref<any>(null),amount=ref(''),notes=ref(''),reviewStatus=ref('approved'),applying=ref(false)
const exporting=ref(false),fromDate=ref(''),toDate=ref('')
const withdrawalKey=ref(''),withdrawalAmount=ref<number|null>(null)
function openWithdrawal(){applying.value=true;amount.value='';error.value='';withdrawalKey.value=crypto.randomUUID();withdrawalAmount.value=null}
async function exportReport(){exporting.value=true;error.value='';try{if(fromDate.value&&toDate.value&&fromDate.value>toDate.value)throw new Error('开始日期不能晚于结束日期');await downloadDividendReport({from_date:fromDate.value,to_date:toDate.value})}catch(err){error.value=(err as Error).message}finally{exporting.value=false}}
const titles={ledger:'佣金与分红账本',withdrawals:'提现审核',audit:'操作审计'}
async function load(){loading.value=true;error.value='';try{const result=await request<Page>((props.mode==='audit'?'/admin/audit':'/'+props.mode)+query({page:page.value,page_size:15}));rows.value=result.items;total.value=result.total}catch(err){error.value=(err as Error).message}finally{loading.value=false}}
async function submit(){if(busy.value)return;busy.value=true;error.value='';try{if(applying.value){const cents=centsFromInput(amount.value);if(!withdrawalKey.value||(withdrawalAmount.value!==null&&withdrawalAmount.value!==cents))withdrawalKey.value=crypto.randomUUID();withdrawalAmount.value=cents;await request('/withdrawals',{method:'POST',body:JSON.stringify({amount_cents:cents,idempotency_key:withdrawalKey.value})});withdrawalKey.value=crypto.randomUUID();withdrawalAmount.value=null}else await request(`/withdrawals/${selected.value.id}/review`,{method:'POST',body:JSON.stringify({status:reviewStatus.value,notes:notes.value})});selected.value=null;applying.value=false;success.value='申请或审核已提交，支付到账以真实通道结果为准';await load()}catch(err){error.value=(err as Error).message}finally{busy.value=false}}
watch(()=>props.mode,()=>{page.value=1;success.value='';load()});onMounted(load)
</script>
<template>
  <div class="page-heading"><div><h1>{{ titles[mode] }}</h1><p>{{ mode==='ledger'?'查看逐单利润分配、结算及退款冲销记录。':mode==='withdrawals'?'审核提现申请。真实转账结果必须由渠道或实际付款凭证确认。':'记录业务修改、审核与财务动作的操作者及结果。' }}</p></div><button v-if="mode==='withdrawals'&&session.role!=='platform'" class="button primary" @click="openWithdrawal">申请提现</button><button v-if="mode==='ledger'&&can('reports')" class="button" :disabled="exporting" @click="exportReport">{{ exporting?'正在导出…':'导出 Excel 报表' }}</button><button class="button" @click="load">刷新</button></div><p v-if="error&&!selected&&!applying" class="notice danger" role="alert">{{ error }}</p><p v-if="success" class="notice success">{{ success }}</p>
  <section class="panel"><div v-if="mode==='ledger'&&can('reports')" class="filter-bar"><span>Excel 导出日期范围</span><label><span>开始日期</span><input v-model="fromDate" type="date" /></label><label><span>结束日期</span><input v-model="toDate" type="date" /></label><small class="muted">仅筛选导出报表，列表继续显示全部授权流水</small></div><div class="filter-bar"><span class="eyebrow">{{ mode==='audit'?'业务变更记录':'财务流水' }}</span><span class="record-count">共 {{ total }} 条</span></div><div class="table-scroll"><table><thead><tr><th>流水编号</th><template v-if="mode!=='audit'"><th>订单 / 用户</th><th>金额</th><th>类别</th><th>状态</th></template><template v-else><th>操作人</th><th>操作</th><th>关联对象</th></template><th>创建时间</th><th v-if="mode==='withdrawals'&&session.role==='platform'">操作</th></tr></thead><tbody><tr v-if="loading"><td colspan="7" class="empty">正在加载…</td></tr><tr v-else-if="!rows.length"><td colspan="7" class="empty"><div class="empty-mark">≡</div>暂无记录</td></tr><tr v-for="row in rows" v-else :key="row.id"><td class="muted">#{{ row.id }}</td><template v-if="mode!=='audit'"><td>{{ row.order_id?`订单 #${row.order_id} / `:'' }}用户 #{{ row.user_id }}</td><td class="cell-title">{{ money(row.amount_cents) }}</td><td>{{ row.beneficiary_role||row.role||row.kind||row.type||'提现' }}</td><td><StatusBadge :value="row.state||row.status" /></td></template><template v-else><td>#{{ row.actor_id||row.user_id }}</td><td>{{ row.action }}</td><td>{{ row.resource_type||row.entity_type }} #{{ row.resource_id||row.entity_id }}</td></template><td>{{ dateTime(row.created_at) }}</td><td v-if="mode==='withdrawals'&&session.role==='platform'"><button v-if="row.status==='pending'" class="text-button" @click="selected=row;notes='';reviewStatus='approved';error=''">审核</button><span v-else class="muted">已处理</span></td></tr></tbody></table></div><div class="pagination"><span>第 {{ page }} 页</span><button class="button small" :disabled="page<=1||loading" @click="page--;load()">上一页</button><button class="button small" :disabled="page*15>=total||loading" @click="page++;load()">下一页</button></div></section>
  <Modal v-if="selected||applying" :title="applying?'申请提现':`审核提现 #${selected.id}`" @close="!busy&&(selected=null,applying=false)"><form id="finance-form" class="form-grid" @submit.prevent="submit"><p v-if="error" class="notice danger span-all" role="alert">{{ error }}</p><label v-if="applying" class="span-all"><span>申请金额（元） *</span><input v-model="amount" inputmode="decimal" :disabled="busy" required /></label><template v-else><div class="notice span-all">申请金额：{{ money(selected.amount_cents) }}。审核通过不等同于银行到账。</div><label class="span-all"><span>审核结果</span><select v-model="reviewStatus"><option value="approved">审核通过</option><option value="rejected">驳回申请</option></select></label><label class="span-all"><span>审核说明 *</span><textarea v-model="notes" rows="4" required /></label></template></form><template #footer><button class="button" :disabled="busy" @click="selected=null;applying=false">取消</button><button class="button primary" form="finance-form" :disabled="busy">{{ busy?'正在提交…':'确认提交' }}</button></template></Modal>
</template>
